package com.meshcrossway.android;

import android.content.*;
import android.database.Cursor;
import android.database.sqlite.*;
import android.os.*;
import java.util.*;
import java.io.*;
import org.json.*;
import static com.meshcrossway.android.MeshData.*;
import com.meshcrossway.android.MeshData.Message;

/** Private durable data. Keys always include network + radio; channel topics include key fingerprint.
 * All production database access runs on a dedicated worker. No payloads/keys are logged. */
final class HistoryStore extends SQLiteOpenHelper {
    private final HandlerThread thread=new HandlerThread("mesh-history");private final Handler worker,main=new Handler(Looper.getMainLooper());
    final EnumMap<RadioProfile,Snapshot> snapshots=new EnumMap<>(RadioProfile.class);private final EnumMap<RadioProfile,String> radios=new EnumMap<>(RadioProfile.class);
    int historyLimit=2000;
    final List<Poi> pois=new ArrayList<>();
    Runnable listener;String error="";private boolean closed;
    private final Runnable reloadTask=this::reload;
    private final LinkedHashMap<String,ContentValues> pendingNodes=new LinkedHashMap<>();private boolean nodeFlushQueued;
    private final Context context;
    HistoryStore(Context context){this(context,"meshcrossway-history.db");}
    HistoryStore(Context context,String name){super(context,name,null,5);this.context=context.getApplicationContext();thread.start();worker=new Handler(thread.getLooper());for(RadioProfile p:RadioProfile.values())snapshots.put(p,Snapshot.empty());}
    @Override public void onConfigure(SQLiteDatabase db){db.enableWriteAheadLogging();}
    @Override public void onCreate(SQLiteDatabase db){
        db.execSQL("CREATE TABLE nodes(network TEXT,radio TEXT,id TEXT,name TEXT,key TEXT,heard INTEGER,lat REAL,lon REAL,position INTEGER,battery INTEGER,type INTEGER,blocked INTEGER,PRIMARY KEY(network,radio,id))");
        db.execSQL("CREATE TABLE channels(network TEXT,radio TEXT,slot INTEGER,name TEXT,identity_hash TEXT,enabled INTEGER,PRIMARY KEY(network,radio,slot))");
        db.execSQL("CREATE TABLE messages(network TEXT,radio TEXT,uid TEXT,topic TEXT,title TEXT,sender TEXT,body TEXT,state TEXT,time INTEGER,outgoing INTEGER,is_read INTEGER,peer TEXT,identity_hash TEXT,slot INTEGER,is_group INTEGER,PRIMARY KEY(network,radio,uid))");
        db.execSQL("CREATE INDEX message_scope_time ON messages(network,radio,time)");
        db.execSQL("CREATE INDEX message_conversation ON messages(network,radio,topic,is_read)");
        createLocalTables(db);addReceiveMetadata(db);addNodeMetadata(db);
        db.execSQL("CREATE TABLE drafts(network TEXT,radio TEXT,topic TEXT,body TEXT,PRIMARY KEY(network,radio,topic))");
    }
    private void createLocalTables(SQLiteDatabase db){
        db.execSQL("CREATE TABLE IF NOT EXISTS flags(network TEXT,radio TEXT,kind TEXT,target TEXT,favorite INTEGER DEFAULT 0,pinned INTEGER DEFAULT 0,muted INTEGER DEFAULT 0,favorite_updated INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(network,radio,kind,target))");
        db.execSQL("CREATE TABLE IF NOT EXISTS pois(uid TEXT PRIMARY KEY,name TEXT,lat REAL,lon REAL,created INTEGER)");
    }
    @Override public void onUpgrade(SQLiteDatabase db,int old,int version){if(old<2)createLocalTables(db);if(old<3)addReceiveMetadata(db);if(old<4)addFavoriteTimestamp(db);if(old<5)addNodeMetadata(db);}
    private void addNodeMetadata(SQLiteDatabase db){db.execSQL("ALTER TABLE nodes ADD COLUMN node_meta TEXT NOT NULL DEFAULT '{}' ");}
    private static String encodeNode(Node n){try{JSONObject root=new JSONObject().put("shortName",n.shortName).put("status",n.status).put("statusKnown",n.statusKnown).put("licensed",n.licensed).put("hardware",n.hardwareModel).put("role",n.role).put("metrics",new JSONObject(n.metrics)).put("history",new JSONArray(n.metricHistory));return root.toString();}catch(JSONException e){return "{}";}}
    private static void decodeNode(Node n,String value){try{JSONObject root=new JSONObject(value);n.shortName=root.optString("shortName","");n.status=root.optString("status","");n.statusKnown=root.optBoolean("statusKnown",false);n.licensed=root.optBoolean("licensed",false);n.hardwareModel=root.optInt("hardware",0);n.role=root.optInt("role",0);JSONObject metrics=root.optJSONObject("metrics");if(metrics!=null){Iterator<String> keys=metrics.keys();while(keys.hasNext()&&n.metrics.size()<16){String key=keys.next();n.metrics.put(key,metrics.optString(key,""));}}JSONArray history=root.optJSONArray("history");if(history!=null)for(int i=Math.max(0,history.length()-20);i<history.length();i++)n.metricHistory.add(history.optString(i,""));}catch(JSONException ignored){}}
    private void addReceiveMetadata(SQLiteDatabase db){db.execSQL("ALTER TABLE messages ADD COLUMN rx_meta TEXT NOT NULL DEFAULT '{}' ");}
    private void addFavoriteTimestamp(SQLiteDatabase db){try(Cursor c=db.rawQuery("PRAGMA table_info(flags)",null)){while(c.moveToNext())if("favorite_updated".equals(c.getString(c.getColumnIndexOrThrow("name"))))return;}db.execSQL("ALTER TABLE flags ADD COLUMN favorite_updated INTEGER NOT NULL DEFAULT 0");}
    private static String encodeRx(RxInfo r){try{JSONObject j=new JSONObject().put("hops",r.hops).put("kind",r.kind).put("width",r.width).put("path",r.path).put("observed",r.observed).put("mqtt",r.mqtt).put("relay",r.relay).put("packetId",r.packetId).put("source",r.source).put("replyId",r.replyId).put("emoji",r.emoji);if(Double.isFinite(r.snr))j.put("snr",r.snr);if(r.rssi!=Integer.MIN_VALUE)j.put("rssi",r.rssi);return j.toString();}catch(JSONException e){return "{}";}}
    private static RxInfo decodeRx(String value){RxInfo r=new RxInfo();try{JSONObject j=new JSONObject(value);r.packetId=j.optLong("packetId",0)&0xffffffffL;r.source=j.optLong("source",0)&0xffffffffL;r.replyId=j.optLong("replyId",0)&0xffffffffL;r.emoji=j.optBoolean("emoji",false);int hops=j.optInt("hops",-1);if(hops>=0&&hops<=63)r.hops=hops;r.kind=j.optString("kind","");if(!Arrays.asList("","flood","direct","meshtastic").contains(r.kind))r.kind="";r.snr=j.optDouble("snr",Double.NaN);r.rssi=j.optInt("rssi",Integer.MIN_VALUE);r.relay=j.optInt("relay",-1);if(r.relay<0||r.relay>255)r.relay=-1;r.mqtt=j.optBoolean("mqtt",false);int width=j.optInt("width",1);String path=j.optString("path","");if(width>=1&&width<=3&&path.matches("[0-9a-f]*")&&path.length()<=128&&path.length()%(2*width)==0){r.width=width;r.path=path;r.observed=j.optBoolean("observed",false)&&r.kind.equals("flood")&&r.hops==path.length()/(2*width);}}catch(JSONException ignored){}return r;}
    void flag(RadioProfile p,String r,String kind,String target,String field,boolean enabled){
        if(!Arrays.asList("favorite","pinned","muted").contains(field)||!Arrays.asList("node","chat").contains(kind))throw new IllegalArgumentException();
        work(db->{ContentValues v=scope(p,r);v.put("kind",kind);v.put("target",target);try(Cursor c=db.query("flags",new String[]{"favorite","pinned","muted","favorite_updated"},"network=? AND radio=? AND kind=? AND target=?",new String[]{p.name(),r,kind,target},null,null,null)){if(c.moveToFirst())for(String key:new String[]{"favorite","pinned","muted","favorite_updated"})v.put(key,l(c,key));}v.put(field,enabled?1:0);if(field.equals("favorite"))v.put("favorite_updated",System.currentTimeMillis()/1000);db.insertWithOnConflict("flags",null,v,SQLiteDatabase.CONFLICT_REPLACE);});
    }
    private static boolean truthy(JSONObject row,String... keys){for(String key:keys){if(!row.has(key)||row.isNull(key))continue;Object value=row.opt(key);if(value instanceof Boolean)return (Boolean)value;if(value instanceof Number)return ((Number)value).doubleValue()!=0;return "true".equalsIgnoreCase(String.valueOf(value))||"1".equals(value);}return false;}
    void cloudMessages(RadioProfile p,String radio,java.util.function.Consumer<JSONArray> callback){worker.post(()->{JSONArray rows=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT m.uid,m.topic,m.time,m.sender,m.title,m.body,m.outgoing,m.is_read,m.peer,m.identity_hash,m.slot,m.is_group,m.state,m.rx_meta FROM messages m LEFT JOIN flags f ON f.network=m.network AND f.radio=m.radio AND f.kind='chat' AND f.target=m.topic WHERE m.network=? AND m.radio=? AND (m.time>=? OR f.favorite=1) ORDER BY m.time",new String[]{p.name(),radio,Long.toString(System.currentTimeMillis()/1000-7L*24*60*60)})){while(c.moveToNext())rows.put(new JSONObject().put("network",p.name()).put("conversationId",c.getString(1)).put("messageId",c.getString(0)).put("sentAt",c.getLong(2)).put("sender",c.getString(3)).put("title",c.getString(4)).put("body",c.getString(5)).put("outgoing",c.getInt(6)==1).put("read",c.getInt(7)==1).put("peer",c.getString(8)).put("identity",c.getString(9)).put("slot",c.getInt(10)).put("group",c.getInt(11)==1).put("state",c.getString(12)).put("rxMeta",c.getString(13)));}catch(Exception ignored){rows=null;}JSONArray result=rows;main.post(()->callback.accept(result));});}
    void cloudFavorites(RadioProfile p,String radio,java.util.function.Consumer<JSONArray> callback){worker.post(()->{JSONArray rows=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT target,favorite,favorite_updated FROM flags WHERE network=? AND radio=? AND kind='chat' AND favorite_updated>0",new String[]{p.name(),radio})){while(c.moveToNext())rows.put(new JSONObject().put("network",p.name()).put("conversationId",c.getString(0)).put("favorite",c.getInt(1)==1).put("updatedAt",c.getLong(2)));}catch(Exception ignored){rows=null;}JSONArray result=rows;main.post(()->callback.accept(result));});}
    void mergeCloudFavorites(RadioProfile p,String radio,JSONArray rows,Runnable done){work(db->{for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null||!p.name().equals(row.optString("network")))continue;String target=row.optString("conversation_id",row.optString("conversationId",""));long updated=row.optLong("updated_at",row.optLong("updatedAt",0));if(target.isEmpty()||target.length()>512||updated<=0)continue;try(Cursor c=db.query("flags",new String[]{"favorite_updated","pinned","muted"},"network=? AND radio=? AND kind='chat' AND target=?",new String[]{p.name(),radio,target},null,null,null)){if(c.moveToFirst()&&c.getLong(0)>updated)continue;ContentValues v=scope(p,radio);v.put("kind","chat");v.put("target",target);v.put("favorite",truthy(row,"favorite")?1:0);v.put("favorite_updated",updated);if(c.moveToFirst()){v.put("pinned",c.getInt(1));v.put("muted",c.getInt(2));}db.insertWithOnConflict("flags",null,v,SQLiteDatabase.CONFLICT_REPLACE);}}if(done!=null)main.post(done);});}
    void mergeCloudMessages(RadioProfile p,String radio,JSONArray rows,Runnable done){work(db->{for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null||!p.name().equals(row.optString("network")))continue;String uid=row.optString("message_id",row.optString("messageId","")),topic=row.optString("conversation_id",row.optString("conversationId",""));long time=row.optLong("sent_at",row.optLong("sentAt",0));String body=row.optString("body","");if(uid.isEmpty()||uid.length()>160||topic.isEmpty()||topic.length()>512||time<=0||body.length()>4096)continue;ContentValues v=scope(p,radio);v.put("uid",uid);v.put("topic",topic);v.put("time",time);v.put("sender",row.optString("sender",""));v.put("title",row.optString("title",""));v.put("body",body);v.put("outgoing",truthy(row,"outgoing")?1:0);v.put("is_read",truthy(row,"is_read","read")?1:0);v.put("peer",row.optString("peer",""));v.put("identity_hash",row.optString("identity_hash",row.optString("identity","")));v.put("slot",row.optInt("slot",0));v.put("is_group",truthy(row,"is_group","group")?1:0);v.put("state",row.optString("state",truthy(row,"outgoing")?"radio accepted":"received"));v.put("rx_meta",row.optString("rx_meta",row.optString("rxMeta","{}")));db.insertWithOnConflict("messages",null,v,SQLiteDatabase.CONFLICT_IGNORE);if(truthy(row,"is_read","read")){ContentValues read=new ContentValues();read.put("is_read",1);db.update("messages",read,"network=? AND radio=? AND uid=? AND topic=? AND is_read=0",new String[]{p.name(),radio,uid,topic});}}if(done!=null)main.post(done);});}
    void poi(String name,double lat,double lon){if(!GeoMath.valid(lat,lon)||name.trim().isEmpty())return;ContentValues v=new ContentValues();v.put("uid",UUID.randomUUID().toString());v.put("name",name.substring(0,Math.min(80,name.length())));v.put("lat",lat);v.put("lon",lon);v.put("created",System.currentTimeMillis()/1000);work(db->db.insertOrThrow("pois",null,v));}
    void deletePoi(String id){work(db->db.delete("pois","uid=?",new String[]{id}));}

    private interface Work {void run(SQLiteDatabase db);}
    private void work(Work action){work(action,true);}
    private void work(Work action,boolean refresh){if(closed)return;worker.post(()->{try{action.run(getWritableDatabase());main.post(()->{error="";if(refresh){main.removeCallbacks(reloadTask);main.postDelayed(reloadTask,150);}});}catch(SQLiteException e){main.post(()->{error="History storage unavailable • do not uninstall; free phone storage and reopen";if(listener!=null)listener.run();});}});}
    void select(RadioProfile p,String radio){radios.put(p,radio);snapshots.put(p,Snapshot.empty());reload();}
    private static ContentValues scope(RadioProfile p,String r){ContentValues v=new ContentValues();v.put("network",p.name());v.put("radio",r);return v;}
    void node(RadioProfile p,String r,Node n){ContentValues v=scope(p,r);v.put("id",n.id);v.put("name",n.name);v.put("key",n.key);v.put("heard",n.heard);v.put("lat",n.lat);v.put("lon",n.lon);v.put("position",n.position?1:0);v.put("battery",n.battery);v.put("type",n.type);v.put("blocked",n.unmessagable?1:0);v.put("node_meta",encodeNode(n));if(closed)return;worker.post(()->{pendingNodes.put(p.name()+"|"+r+"|"+n.id,v);if(!nodeFlushQueued){nodeFlushQueued=true;worker.postDelayed(this::flushNodes,100);}});}
    private void flushNodes(){nodeFlushQueued=false;if(pendingNodes.isEmpty())return;try{SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{for(ContentValues v:pendingNodes.values()){try(Cursor existing=db.query("nodes",new String[]{"node_meta"},"network=? AND radio=? AND id=?",new String[]{v.getAsString("network"),v.getAsString("radio"),v.getAsString("id")},null,null,null)){if(existing.moveToFirst()){Node previous=new Node(),next=new Node();decodeNode(previous,existing.getString(0));decodeNode(next,v.getAsString("node_meta"));previous.metrics.putAll(next.metrics);for(String sample:next.metricHistory)if(!previous.metricHistory.contains(sample))previous.metricHistory.add(sample);while(previous.metricHistory.size()>20)previous.metricHistory.remove(0);previous.licensed=next.licensed;previous.shortName=next.shortName;previous.hardwareModel=next.hardwareModel;previous.role=next.role;if(next.statusKnown){previous.status=next.status;previous.statusKnown=true;}v.put("node_meta",encodeNode(previous));}}db.insertWithOnConflict("nodes",null,v,SQLiteDatabase.CONFLICT_REPLACE);}db.setTransactionSuccessful();}finally{db.endTransaction();}pendingNodes.clear();main.post(()->{main.removeCallbacks(reloadTask);main.postDelayed(reloadTask,100);});}catch(SQLiteException e){main.post(()->{error="Node history could not be saved • check storage";if(listener!=null)listener.run();});}}
    void channel(RadioProfile p,String r,Channel c){ContentValues v=scope(p,r);v.put("slot",c.slot);v.put("name",c.name);v.put("identity_hash",c.identity);v.put("enabled",c.enabled?1:0);work(db->{db.beginTransaction();try{if(p==RadioProfile.MESHTASTIC&&!c.legacyIdentity.isEmpty()){String oldTopic="c:"+c.slot+":"+c.legacyIdentity,newTopic=c.topic();ContentValues msg=new ContentValues();msg.put("topic",newTopic);msg.put("identity_hash",c.identity);db.update("messages",msg,"network=? AND radio=? AND topic=?",new String[]{p.name(),r,oldTopic});db.execSQL("UPDATE OR IGNORE drafts SET topic=? WHERE network=? AND radio=? AND topic=?",new Object[]{newTopic,p.name(),r,oldTopic});db.execSQL("UPDATE OR IGNORE flags SET target=? WHERE network=? AND radio=? AND kind='chat' AND target=?",new Object[]{newTopic,p.name(),r,oldTopic});}db.insertWithOnConflict("channels",null,v,SQLiteDatabase.CONFLICT_REPLACE);db.setTransactionSuccessful();}finally{db.endTransaction();}});}
    private ContentValues messageValues(RadioProfile p,String r,Message m){ContentValues v=scope(p,r);v.put("uid",m.uid);v.put("topic",m.topic);v.put("title",m.title);v.put("sender",m.sender);v.put("body",m.body);v.put("state",m.state);v.put("time",m.timestamp);v.put("outgoing",m.outgoing?1:0);v.put("is_read",m.read?1:0);v.put("peer",m.peer);v.put("identity_hash",m.identity);v.put("slot",m.slot);v.put("is_group",m.group?1:0);v.put("rx_meta",encodeRx(m.rx));return v;}
    void message(RadioProfile p,String r,Message m){message(p,r,m,null);}
    void message(RadioProfile p,String r,Message m,java.util.function.Consumer<Boolean> inserted){ContentValues v=messageValues(p,r,m);work(db->{long row=db.insertWithOnConflict("messages",null,v,SQLiteDatabase.CONFLICT_IGNORE);if(row<0){try(Cursor existing=db.query("messages",new String[]{"rx_meta"},"network=? AND radio=? AND uid=?",new String[]{p.name(),r,m.uid},null,null,null)){if(existing.moveToFirst()){ContentValues meta=new ContentValues();meta.put("rx_meta",encodeRx(RxInfo.merge(decodeRx(existing.getString(0)),m.rx)));db.update("messages",meta,"network=? AND radio=? AND uid=?",new String[]{p.name(),r,m.uid});}}}if(row>=0&&inserted!=null){boolean muted=false;try(Cursor c=db.query("flags",new String[]{"muted"},"network=? AND radio=? AND kind='chat' AND target=?",new String[]{p.name(),r,m.topic},null,null,null)){if(c.moveToFirst())muted=c.getInt(0)==1;}boolean quiet=muted;main.post(()->inserted.accept(quiet));}});}
    void outgoing(RadioProfile p,String r,Message m,Runnable onSaved,Runnable onError){ContentValues v=messageValues(p,r,m);if(closed){onError.run();return;}worker.post(()->{try{long row=getWritableDatabase().insertOrThrow("messages",null,v);if(row<0)throw new SQLiteException();main.post(()->{onSaved.run();reload();});}catch(SQLiteException e){main.post(()->{error="Could not save message • transmission cancelled";onError.run();if(listener!=null)listener.run();});}});}
    void delivery(RadioProfile p,String r,String uid,String state){work(db->{
        // Late BLE callbacks cannot downgrade an acknowledged or accepted packet.
        String extra=state.equals("submitted")?" AND state='queued'":state.equals("radio accepted")?" AND state IN ('queued','submitted','uncertain')":state.equals("uncertain")?" AND state IN ('queued','submitted','radio accepted')":" AND state!='delivered'";
        ContentValues v=new ContentValues();v.put("state",state);db.update("messages",v,"network=? AND radio=? AND uid=?"+extra,new String[]{p.name(),r,uid});});}
    void uncertain(RadioProfile p,String r){work(db->{ContentValues v=new ContentValues();v.put("state","uncertain");db.update("messages",v,"network=? AND radio=? AND outgoing=1 AND state IN ('queued','submitted','radio accepted')",new String[]{p.name(),r});});}
    void read(RadioProfile p,String r,String topic){work(db->{ContentValues v=new ContentValues();v.put("is_read",1);db.update("messages",v,"network=? AND radio=? AND topic=? AND is_read=0",new String[]{p.name(),r,topic});});}
    void draft(RadioProfile p,String r,String topic,String body){ContentValues v=scope(p,r);v.put("topic",topic);v.put("body",body);work(db->db.insertWithOnConflict("drafts",null,v,SQLiteDatabase.CONFLICT_REPLACE),false);}
    void loadDraft(RadioProfile p,String r,String topic,java.util.function.Consumer<String> callback){if(closed)return;worker.post(()->{String body="";try(Cursor c=getReadableDatabase().query("drafts",new String[]{"body"},"network=? AND radio=? AND topic=?",new String[]{p.name(),r,topic},null,null,null)){if(c.moveToFirst())body=c.getString(0);}catch(SQLiteException ignored){}String result=body;main.post(()->callback.accept(result));});}
    private void reload(){
        if(closed)return;EnumMap<RadioProfile,String> selection=new EnumMap<>(radios);
        worker.post(()->{try{EnumMap<RadioProfile,Snapshot> result=new EnumMap<>(RadioProfile.class);for(Map.Entry<RadioProfile,String> entry:selection.entrySet())result.put(entry.getKey(),load(getReadableDatabase(),entry.getKey(),entry.getValue(),historyLimit));
            ArrayList<Poi> points=new ArrayList<>();try(Cursor c=getReadableDatabase().query("pois",null,null,null,null,null,"created DESC","1000")){while(c.moveToNext()){Poi point=new Poi();point.id=s(c,"uid");point.name=s(c,"name");point.lat=c.getDouble(c.getColumnIndexOrThrow("lat"));point.lon=c.getDouble(c.getColumnIndexOrThrow("lon"));point.created=l(c,"created");points.add(point);}}
            main.post(()->{if(!selection.equals(radios)||closed)return;snapshots.putAll(result);pois.clear();pois.addAll(points);if(listener!=null)listener.run();});
        }catch(SQLiteException e){main.post(()->{error="History could not be loaded";if(listener!=null)listener.run();});}});
    }
    void older(){historyLimit=Math.min(20000,historyLimit+2000);reload();}
    static Snapshot load(SQLiteDatabase db,RadioProfile p,String r){return load(db,p,r,2000);}
    static Snapshot load(SQLiteDatabase db,RadioProfile p,String r,int limit){String where="network=? AND radio=?";String[] args={p.name(),r};ArrayList<Node> ns=new ArrayList<>();ArrayList<Channel> cs=new ArrayList<>();ArrayList<Message> ms=new ArrayList<>();
        try(Cursor c=db.query("nodes",null,where,args,null,null,"heard DESC","4096")){while(c.moveToNext()){Node n=new Node();n.id=s(c,"id");n.name=s(c,"name");n.key=s(c,"key");n.heard=l(c,"heard");n.lat=c.getDouble(c.getColumnIndexOrThrow("lat"));n.lon=c.getDouble(c.getColumnIndexOrThrow("lon"));n.position=l(c,"position")==1;n.battery=(int)l(c,"battery");n.type=(int)l(c,"type");n.unmessagable=l(c,"blocked")==1;decodeNode(n,s(c,"node_meta"));ns.add(n);}}
        try(Cursor c=db.query("channels",null,where,args,null,null,"slot ASC")){while(c.moveToNext()){Channel channel=new Channel();channel.slot=(int)l(c,"slot");channel.name=s(c,"name");channel.identity=s(c,"identity_hash");channel.enabled=l(c,"enabled")==1;cs.add(channel);}}
        try(Cursor c=db.query("messages",null,where,args,null,null,"time DESC,rowid DESC",Integer.toString(limit))){while(c.moveToNext()){Message m=new Message();m.uid=s(c,"uid");m.topic=s(c,"topic");m.title=s(c,"title");m.sender=s(c,"sender");m.body=s(c,"body");m.state=s(c,"state");m.timestamp=l(c,"time");m.outgoing=l(c,"outgoing")==1;m.read=l(c,"is_read")==1;m.peer=s(c,"peer");m.identity=s(c,"identity_hash");m.slot=(int)l(c,"slot");m.group=l(c,"is_group")==1;m.rx=decodeRx(s(c,"rx_meta"));ms.add(m);}}
        Collections.reverse(ms);Map<String,Flags> flags=new HashMap<>();try(Cursor c=db.query("flags",null,where,args,null,null,null)){while(c.moveToNext()){Flags f=new Flags();f.favorite=l(c,"favorite")==1;f.pinned=l(c,"pinned")==1;f.muted=l(c,"muted")==1;flags.put(s(c,"kind")+":"+s(c,"target"),f);}}
        return new Snapshot(ns,cs,ms,flags);
    }
    private static final String[] BACKUP_TABLES={"nodes","channels","messages","drafts","flags","pois"};
    void exportBackup(OutputStream output,java.util.function.Consumer<String> done){worker.post(()->{try(OutputStream out=output){JSONObject root=new JSONObject();root.put("format","MeshCrosswayAndroid");root.put("version",1);JSONObject tables=new JSONObject();flushNodes();SQLiteDatabase db=getReadableDatabase();db.beginTransaction();try{for(String table:BACKUP_TABLES){JSONArray rows=new JSONArray();try(Cursor c=db.query(table,null,null,null,null,null,null)){while(c.moveToNext()){JSONObject row=new JSONObject();for(int col=0;col<c.getColumnCount();col++){Object v=c.isNull(col)?JSONObject.NULL:c.getType(col)==Cursor.FIELD_TYPE_INTEGER?c.getLong(col):c.getType(col)==Cursor.FIELD_TYPE_FLOAT?c.getDouble(col):c.getString(col);row.put(c.getColumnName(col),v);}rows.put(row);if(rows.length()>100000)throw new IOException("Backup exceeds export row limit");}}tables.put(table,rows);}db.setTransactionSuccessful();}finally{db.endTransaction();}root.put("tables",tables);JSONObject selected=new JSONObject();for(RadioProfile p:RadioProfile.values())selected.put(p.name(),context.getSharedPreferences("radios",Context.MODE_PRIVATE).getString(p.name(),""));root.put("selection",selected);out.write(root.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));main.post(()->done.accept(""));}catch(Exception e){main.post(()->done.accept("Backup could not be written • keep the installed app"));}});}
    void importBackup(InputStream input,java.util.function.Consumer<String> done){worker.post(()->{try(InputStream in=input){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(bytes.size()+n>25*1024*1024)throw new IOException("Backup too large");bytes.write(buffer,0,n);}JSONObject root=new JSONObject(bytes.toString("UTF-8"));if(!root.getString("format").equals("MeshCrosswayAndroid")||root.getInt("version")!=1)throw new IOException("Unsupported backup");JSONObject tables=root.getJSONObject("tables");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{int total=0;for(String table:BACKUP_TABLES){JSONArray rows=tables.optJSONArray(table);if(rows==null)continue;Set<String> columns=new HashSet<>();try(Cursor c=db.rawQuery("SELECT * FROM "+table+" LIMIT 0",null)){columns.addAll(Arrays.asList(c.getColumnNames()));}for(int i=0;i<rows.length();i++){if(++total>100000)throw new IOException("Too many rows");JSONObject row=rows.getJSONObject(i);ContentValues values=new ContentValues();for(String key:columns){if(!row.has(key)||row.isNull(key)){if(key.equals("rx_meta")||key.equals("node_meta"))values.put(key,"{}");else if(key.equals("favorite_updated"))values.put(key,0L);continue;}Object value=row.get(key);if(value instanceof Number){double d=((Number)value).doubleValue();if(!Double.isFinite(d))throw new IOException("Invalid number");if(value instanceof Float||value instanceof Double)values.put(key,d);else values.put(key,((Number)value).longValue());}else{String text=value.toString();if(text.length()>(key.equals("body")?4000:key.equals("rx_meta")?2048:key.equals("node_meta")?32768:512))throw new IOException("Invalid field length");values.put(key,text);}}
        if(values.size()!=columns.size())throw new IOException("Incomplete backup row");
        if(!table.equals("pois")){RadioProfile profile=RadioProfile.valueOf(values.getAsString("network"));String radio=values.getAsString("radio");if(radio==null||radio.isEmpty()||radio.length()>64)throw new IOException("Invalid radio scope");
                            if(table.equals("nodes")){String id=values.getAsString("id");if(profile==RadioProfile.MESHTASTIC){long number=Long.parseLong(id);if(number<=0||number>0xffffffffL)throw new IOException("Invalid node");}else if(id.length()!=64||Wire.unhex(id).length!=32)throw new IOException("Invalid public identity");}
                            if(table.equals("channels")){int slot=values.getAsInteger("slot");if(slot<0||slot>=(profile==RadioProfile.MESHTASTIC?8:256))throw new IOException("Invalid channel");}
                        }
                        if(table.equals("pois")&&!GeoMath.valid(values.getAsDouble("lat"),values.getAsDouble("lon")))throw new IOException("Invalid coordinates");
                        if(table.equals("messages")&&values.getAsInteger("outgoing")==1&&Arrays.asList("queued","submitted","radio accepted").contains(values.getAsString("state")))values.put("state","uncertain");
                        db.insertWithOnConflict(table,null,values,SQLiteDatabase.CONFLICT_IGNORE);
                    }}db.setTransactionSuccessful();}finally{db.endTransaction();}JSONObject selected=root.optJSONObject("selection");if(selected!=null){SharedPreferences pref=context.getSharedPreferences("radios",Context.MODE_PRIVATE);SharedPreferences.Editor edit=pref.edit();for(RadioProfile p:RadioProfile.values()){String address=selected.optString(p.name(),"");if(pref.getString(p.name(),"").isEmpty()&&android.bluetooth.BluetoothAdapter.checkBluetoothAddress(address))edit.putString(p.name(),address).putBoolean(p.name()+".desired",false);}edit.apply();}
                main.post(()->{reload();done.accept("");});}catch(Exception e){main.post(()->done.accept("Backup rejected • existing data was preserved"));}});}
    private static String s(Cursor c,String key){return c.getString(c.getColumnIndexOrThrow(key));}private static long l(Cursor c,String key){return c.getLong(c.getColumnIndexOrThrow(key));}
    @Override public void close(){closed=true;listener=null;main.removeCallbacksAndMessages(null);worker.post(()->{flushNodes();super.close();thread.quitSafely();});}
}

